const items = $input.all();
if (items.length === 0) {
  return [];
}

const runId = (items[0].json.run_id || '—').toString();
function fmt(n) {
  return (Number(n) || 0).toLocaleString('tr-TR');
}

const sorted = items.slice().sort((a, b) => {
  const ka = (a.json.kit_name || '').toString();
  const kb = (b.json.kit_name || '').toString();
  if (ka !== kb) return ka.localeCompare(kb, 'tr');
  return (a.json.sample_id || '').toString().localeCompare((b.json.sample_id || '').toString(), 'tr');
});

const byKit = {};
sorted.forEach(it => {
  const k = it.json.kit_name || '—';
  byKit[k] = (byKit[k] || 0) + 1;
});

const kitSummaryRows = Object.entries(byKit)
  .sort((a, b) => b[1] - a[1])
  .map(([k, c], i, arr) => {
    const border = i < arr.length - 1 ? 'border-bottom:1px solid #e4e7eb;' : '';
    return `<tr>
      <td style="padding:12px 16px;${border}font-size:13px;color:#52606d;">${k}</td>
      <td style="padding:12px 16px;${border}font-size:14px;font-family:'SFMono-Regular',Menlo,Consolas,monospace;color:#102a43;text-align:right;"><strong>${c}</strong></td>
    </tr>`;
  }).join('');

const sampleRows = sorted.map((it, i, arr) => {
  const j = it.json;
  const reads = Number(j.reads) || 0;
  const req = Number(j.required_se_reads) || 0;
  const border = i < arr.length - 1 ? 'border-bottom:1px solid #e4e7eb;' : '';
  const base = `padding:10px 12px;${border}font-size:13px;color:#102a43;`;
  return `<tr>
    <td style="${base}width:32px;color:#7b8794;text-align:right;font-family:'SFMono-Regular',Menlo,Consolas,monospace;">${String(i + 1).padStart(2, '0')}</td>
    <td style="${base}font-family:'SFMono-Regular',Menlo,Consolas,monospace;white-space:nowrap;">${j.sample_id || ''}</td>
    <td style="${base}font-size:12px;color:#52606d;">${j.kit_name || ''}</td>
    <td style="${base}font-size:12px;color:#52606d;white-space:nowrap;"><span style="font-family:'SFMono-Regular',Menlo,Consolas,monospace;">${j.i7_code || ''}${j.i5_code ? ' / ' + j.i5_code : ''}</span>${j.index_kit_name ? `<div style="font-size:10px;color:#9aa5b1;margin-top:2px;font-weight:400;">${j.index_kit_name}</div>` : ''}</td>
    <td style="${base}font-size:12px;color:#52606d;">${j.requester_short_name || j.requester_name || ''}</td>
    <td style="${base}text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;">${fmt(reads)}</td>
    <td style="${base}text-align:right;font-variant-numeric:tabular-nums;color:#7b8794;white-space:nowrap;">${fmt(req)}</td>
  </tr>`;
}).join('');

